class FeedRepositoryImpl(
 private val api:FeedApi,
 private val dao:PostDao,
 private val db:AppDatabase
):FeedRepository{
 override fun observeFeed():Flow<List<Post>> = dao.observeAll().map { rows -> rows.map(PostEntity::toDomain) }
 override suspend fun refresh(){
   val dto=api.getFeed()
   val entities=dto.items.mapNotNull { it.toEntityOrNull() }
   db.withTransaction {
     dao.replaceSnapshot(entities, serverVersion=dto.version)
   }
 }
}

suspend fun sendMessage(conversationId:String,text:String):String = db.withTransaction {
 val clientId=ids.next()
 messageDao.insert(MessageEntity.pending(clientId,conversationId,text,clock.now()))
 outboxDao.insert(OutboxEntity.sendMessage(clientId))
 clientId
}
// Worker/socket sender đọc outbox; ack cập nhật cùng record theo clientId.
